655	            display: block;
656	            animation: slideDown 0.2s ease-out;
657	        }
658	
659	        @keyframes slideDown {
660	            from { opacity: 0; transform: translateY(-4px); }
661	            to { opacity: 1; transform: translateY(0); }
662	        }
663	
664	        .spinner {
665	            display: inline-block;
666	            width: 1.1rem;
667	            height: 1.1rem;
668	            border: 2.5px solid rgba(255, 255, 255, 0.25);
669	            border-top-color: white;
670	            border-right-color: rgba(255, 255, 255, 0.8);
671	            border-radius: 50%;
672	            animation: spin 0.7s linear infinite;
673	            margin-right: 0.5rem;
674	            vertical-align: middle;
675	        }
676	
677	        .spinner::after {
678	            content: ' ';
679	        }
680	
681	        @keyframes spin {
682	            to { transform: rotate(360deg); }
683	        }
